#include "test_platform.hpp"
#include "edudb.hpp"
#include "mvto_control.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <random>
#include <thread>
using namespace edudb;namespace fs=std::filesystem;
static unsigned checks=0;static json events=json::array();
static void need(bool b,const std::string& m){++checks;if(!b)throw std::runtime_error(m);}
static json sql(Engine& e,const std::string& s,const std::string& q,bool ok=true){auto r=e.execute(s,q);events.push_back({{"session",s},{"sql",q},{"response",r}});if(ok)need(r.value("ok",false),q+" => "+r.value("error",json()).dump());return r;}
static void error(Engine& e,const std::string& s,const std::string& q,const std::string& code){auto r=sql(e,s,q,false);need(!r.value("ok",true)&&r.at("error").at("code")==code,q+" requires "+code);}
static void value(Engine& e,const std::string& s,long long v,int id=1){auto r=sql(e,s,"SELECT v FROM t WHERE id="+std::to_string(id));need(r.at("rows")==json::array({json::array({v})}),"actual typed SQL value "+std::to_string(v));need(r.at("locking").at("effective")=="VERSION_WTS_RTS","actual MVTO plan, not SI alias");}
static std::uint64_t begin(Engine& e,const std::string& s,bool ro=false){return sql(e,s,"BEGIN PROTOCOL MVTO READ "+std::string(ro?"ONLY":"WRITE")).at("tx_id");}
static std::uint64_t timestamp(const json& d,std::uint64_t id){for(auto& t:d.at("storage").at("transactions").at("active_transactions"))if(t.at("tx_id")==id)return t.at("start_timestamp");throw std::runtime_error("timestamp context missing");}
static void no_table_locks(const json& d,std::uint64_t tx){for(auto& l:d.at("locks"))if(l.at("tx_id")==tx){auto n=l.at("resource").get<std::string>();need(n.rfind("table:",0)!=0&&n.rfind("cluster:",0)!=0,"MVTO does not hide coarse user-data locks");}}
static void write(const fs::path& p,const json& j){std::ofstream f(p,std::ios::binary|std::ios::trunc);f<<j.dump(2);f.flush();if(!f)throw std::runtime_error("receipt write failed");}
static void module(){
 PageMvto c(1000);c.ensure_current(1,10);c.read(1,10,5);bool rejected=false;try{c.validate_write(1,10,10,4);}catch(const DbError& ex){rejected=ex.code=="MVTO_RTS_CONFLICT";}need(rejected,"module younger RTS rejects old writer");c.validate_write(1,10,10,5);c.prepare_publish({1});c.publish(1,20,6);need(c.select(1,{10,20},3)==10,"old reader selects old WTS");need(c.select(1,{10,20},8)==20,"young reader selects latest eligible WTS");
 rejected=false;try{c.validate_write(1,10,20,5);}catch(const DbError& ex){rejected=ex.code=="MVTO_WRITE_CONFLICT";}need(rejected,"changed physical whole-page base rejected");
 // Independent scalar model of ordered version timestamps, including RTS max.
 std::map<std::uint64_t,std::pair<std::uint64_t,std::uint64_t>> model{{10,{0,5}},{20,{6,6}}};std::vector<std::uint64_t> available{10,20};std::mt19937 random(151561);std::uint64_t lsn=20,wts=6;
 for(unsigned i=0;i<800;++i){if(i%10==0){lsn+=10;wts+=3;c.prepare_publish({1});c.publish(1,lsn,wts);available.push_back(lsn);model[lsn]={wts,wts};}auto ts=std::uint64_t(random()%(wts+6));std::uint64_t selected=0,best=0;for(auto& v:model)if(v.second.first<=ts&&(!selected||v.second.first>best)){selected=v.first;best=v.second.first;}need(c.select(1,available,ts)==selected,"seeded independent WTS choice");c.read(1,selected,ts);model[selected].second=std::max(model[selected].second,ts);}
 auto diag=c.diagnostics();need(diag.at("metadata_slots")==model.size(),"actual version slots");for(auto& v:diag.at("versions")){auto p=model.at(v.at("lsn"));need(v.at("wts")==p.first&&v.at("rts")==p.second,"independent exact WTS/RTS");}
 c.collect({{1,{10}}});need(c.diagnostics().at("metadata_slots")==2,"keep only historical target plus latest");c.reset();need(c.diagnostics().at("metadata_slots")==0,"metadata epoch reset");
 PageMvto bounded(2);bounded.ensure_current(1,1);bounded.prepare_publish({1});bounded.publish(1,2,2);rejected=false;try{bounded.prepare_publish({1});}catch(const DbError& e){rejected=e.code=="MVTO_METADATA_LIMIT";}need(rejected,"pre-WAL timestamp publication bound");
}
static void sql_splits(Engine& e,json& proof){
 auto setup=e.open_session();sql(e,setup,"CREATE TABLE split_rows(id INTEGER PRIMARY KEY,k INTEGER) ORGANIZATION BPLUS(id) WITH(max_keys=5)");sql(e,setup,"INSERT INTO split_rows VALUES(1,1),(2,2)");e.close_session(setup);
 auto old=e.open_session(),young=e.open_session(),latest=e.open_session();
 auto rows=[&](const std::string& sid,int n){auto r=sql(e,sid,"SELECT id FROM split_rows USE SCAN ORDER BY id");json expected=json::array();for(int i=1;i<=n;++i)expected.push_back(json::array({i}));need(r.at("rows")==expected,"actual SQL across split-page versions "+std::to_string(n));};
 auto inspect=[&](const std::string& sid){auto j=e.inspect(sid,{{"table","split_rows"},{"index","__organization"},{"max_pages",2048}});events.push_back({{"inspect_split_rows",j}});need(j.value("ok",false),"inspect SQL-visible BPLUS organization");return j.at("inspection").at("structure");};
 begin(e,old);auto original=inspect(old);std::string q="INSERT INTO split_rows VALUES ";for(int i=3;i<=48;++i){if(i>3)q+=",";q+="("+std::to_string(i)+","+std::to_string(i)+")";}sql(e,old,q);begin(e,young,true);auto pending=e.diagnostics();sql(e,old,"COMMIT");rows(young,48);auto first=inspect(young);need(first.at("root")!=original.at("root"),"older writer created a new root after younger BEGIN");need(first.at("nodes").get<unsigned>()>original.at("nodes").get<unsigned>(),"actual new physical access pages");proof["older_writer_new_root"]={{"before",original},{"after",first},{"reader_begin_before_commit",pending}};sql(e,young,"COMMIT");
 begin(e,old,true);rows(old,48);auto oldroot=inspect(old);begin(e,young);q="INSERT INTO split_rows VALUES ";for(int i=49;i<=180;++i){if(i>49)q+=",";q+="("+std::to_string(i)+","+std::to_string(i)+")";}sql(e,young,q);sql(e,young,"COMMIT");rows(old,48);auto oldagain=inspect(old);need(oldagain.at("root")==oldroot.at("root")&&oldagain.at("descriptor").at("count")==48,"older reader retains old root and count");begin(e,latest,true);rows(latest,180);auto newroot=inspect(latest);need(newroot.at("root")!=oldroot.at("root"),"younger writer actually grew root");proof["old_reader_after_young_split"]={{"old",oldagain},{"latest",newroot}};sql(e,latest,"COMMIT");sql(e,old,"COMMIT");for(auto& s:std::vector<std::string>{old,young,latest})e.close_session(s);
}
static void native_cursor(const fs::path& dir,json& proof){
 // A real Storage cursor on the actual SQL-created organized file, not a model.
 Storage d(dir.u8string(),8);TransactionOptions o;o.protocol=TransactionProtocol::Mvto;o.read_only=true;auto old=d.begin(o);auto cursor=d.scan(old,"split_rows");StoredRow r;need(cursor->next(r)&&r.values[0]==1,"open real old organization cursor before split");std::vector<int> ids{1};o.read_only=false;auto writer=d.begin(o);for(int id=181;id<=240;++id)d.insert_row(writer,"split_rows",json::array({id,id}));d.commit(writer);while(cursor->next(r))ids.push_back(r.values.at(0).get<int>());std::vector<int> expected;for(int id=1;id<=180;++id)expected.push_back(id);need(ids==expected,"old physical cursor continues across young split/retired pages");need(d.read_table(old,"split_rows",false).at("row_count")==180,"old descriptor snapshot count");proof["native_old_cursor"]={{"original_rows",180},{"actual_rows_after_young_split",ids.size()},{"diagnostics",d.diagnostics()}};d.rollback(old);o.read_only=true;auto now=d.begin(o);need(d.read_table(now,"split_rows",false).at("row_count")==240,"new cursor view sees all committed additions");need(d.verify(now).at("ok")==true,"native structure verify after real SQL/native cursor interleaving");d.rollback(now);
}
static void metadata_budget(const fs::path& dir,json& proof){
 edudb_test::set_env("EDUDB_MVTO_METADATA_SLOTS","6");{Engine e(dir.u8string(),8);auto s=e.open_session();sql(e,s,"CREATE TABLE t(id INTEGER PRIMARY KEY,v INTEGER)");sql(e,s,"INSERT INTO t VALUES(1,10)");e.close_session(s);auto ro=e.open_session(),w=e.open_session();begin(e,ro,true);value(e,ro,10);begin(e,w);sql(e,w,"UPDATE t SET v=11 WHERE id=1");auto before=e.diagnostics();need(before.at("storage").at("transactions").at("mvto").at("metadata_slots")==5,"exact fixture has5 real physical version stamps");error(e,w,"COMMIT","MVTO_METADATA_LIMIT");need(e.diagnostics().at("storage").at("wal_bytes")==before.at("storage").at("wal_bytes"),"metadata budget refusal before WAL");value(e,ro,10);sql(e,w,"ROLLBACK");sql(e,ro,"COMMIT");begin(e,w);sql(e,w,"UPDATE t SET v=12 WHERE id=1");sql(e,w,"COMMIT");begin(e,w,true);value(e,w,12);sql(e,w,"COMMIT");proof["metadata_budget_pre_WAL"]=before;e.close_session(ro);e.close_session(w);}edudb_test::set_env("EDUDB_MVTO_METADATA_SLOTS","");
}
static void normal(const fs::path& path,json& proof){
 module();Engine e(path.u8string(),8);auto setup=e.open_session();sql(e,setup,"CREATE TABLE t(id INTEGER PRIMARY KEY,v INTEGER)");sql(e,setup,"INSERT INTO t VALUES(1,10),(2,20)");e.close_session(setup);
 auto old=e.open_session(),young=e.open_session(),other=e.open_session();auto older=begin(e,old);sql(e,old,"UPDATE t SET v=11 WHERE id=1");auto younger=begin(e,young,true);value(e,young,10);auto d=e.diagnostics();auto ots=timestamp(d,older),yts=timestamp(d,younger);need(ots<yts,"real transaction timestamp order");no_table_locks(d,older);no_table_locks(d,younger);bool seen=false;for(auto& v:d.at("storage").at("transactions").at("mvto").at("versions"))if(v.at("rts").get<std::uint64_t>()>=yts)seen=true;need(seen,"actual version RTS raised by younger SQL reader");proof["rts_before_reject"]=d;auto before=d.at("storage").at("wal_bytes");error(e,old,"COMMIT","MVTO_RTS_CONFLICT");need(e.diagnostics().at("storage").at("wal_bytes")==before,"MVTO RTS refusal before WAL append/force");sql(e,old,"ROLLBACK");value(e,young,10);sql(e,young,"COMMIT");
 // Older reader must bypass a younger committed physical latest version.
 begin(e,old,true);value(e,old,10);begin(e,young);sql(e,young,"UPDATE t SET v=12 WHERE id=1");sql(e,young,"COMMIT");value(e,old,10);proof["old_reader_versions"]=e.diagnostics();sql(e,old,"COMMIT");
 // Distinguish MVTO from fixed BEGIN-CSN/SI: older writer commits after the
 // younger reader begins, but before its first read. WTS is eligible.
 older=begin(e,old);sql(e,old,"UPDATE t SET v=13 WHERE id=1");younger=begin(e,young,true);auto starts=e.diagnostics();need(timestamp(starts,older)<timestamp(starts,younger),"MVTO older-writer test order");sql(e,old,"COMMIT");value(e,young,13);proof["non_SI_first_read"]=e.diagnostics();sql(e,young,"COMMIT");
 // Each physical write reads the base and therefore advances base RTS.
 older=begin(e,old);sql(e,old,"UPDATE t SET v=14 WHERE id=1");younger=begin(e,young);sql(e,young,"UPDATE t SET v=21 WHERE id=2");no_table_locks(e.diagnostics(),older);no_table_locks(e.diagnostics(),younger);before=e.diagnostics().at("storage").at("wal_bytes");error(e,old,"COMMIT","MVTO_RTS_CONFLICT");need(e.diagnostics().at("storage").at("wal_bytes")==before,"same-page disjoint-row writer rejected pre-WAL");sql(e,old,"ROLLBACK");sql(e,young,"COMMIT");begin(e,other,true);value(e,other,13);value(e,other,21,2);sql(e,other,"COMMIT");
 // Ordinary rollback/savepoint correctness and nondecreasing RTS on rollback.
 begin(e,old);sql(e,old,"SAVEPOINT keep");sql(e,old,"UPDATE t SET v=50 WHERE id=1");value(e,old,50);sql(e,old,"ROLLBACK TO keep");value(e,old,13);sql(e,old,"RELEASE SAVEPOINT keep");sql(e,old,"COMMIT");begin(e,old);sql(e,old,"UPDATE t SET v=51 WHERE id=1");sql(e,old,"ROLLBACK");
 begin(e,old);sql(e,old,"SAVEPOINT initial");sql(e,old,"UPDATE t SET v=52 WHERE id=1");begin(e,young,true);value(e,young,13);sql(e,old,"ROLLBACK TO initial");sql(e,old,"UPDATE t SET v=53 WHERE id=1");error(e,old,"COMMIT","MVTO_RTS_CONFLICT");sql(e,old,"ROLLBACK");value(e,young,13);sql(e,young,"COMMIT");
 begin(e,old,true);error(e,old,"UPDATE t SET v=54 WHERE id=1","READ_ONLY_TRANSACTION");sql(e,old,"ROLLBACK");begin(e,old,true);error(e,other,"BEGIN PROTOCOL SNAPSHOT","PROTOCOL_MODE_BUSY");error(e,other,"BEGIN PROTOCOL MV2PL","PROTOCOL_MODE_BUSY");sql(e,old,"COMMIT");sql(e,other,"SET LOCK GRANULARITY RECORD");error(e,other,"BEGIN PROTOCOL MVTO","INVALID_LOCK_GRANULARITY");sql(e,other,"SET LOCK GRANULARITY TABLE");
 begin(e,other,true);value(e,other,13);value(e,other,21,2);auto verified=sql(e,other,"VERIFY");need(verified.at("verification").at("ok")==true,"SQL verify actual current persistent pages/indexes");sql(e,other,"COMMIT");need(e.diagnostics().at("storage").at("transactions").at("mvto").at("metadata_slots")==0,"no MVTO transactions => metadata safe epoch reset");
 for(auto& s:std::vector<std::string>{old,young,other})e.close_session(s);sql_splits(e,proof);
}
int main(int argc,char** argv){fs::path dir=argc>1?fs::u8path(argv[1]):fs::temp_directory_path()/fs::path("edudb-mvto-"+std::to_string(edudb_test::process_id()));auto mode=argc>2?argv[2]:"normal";auto receipt=argc>3?fs::u8path(argv[3]):dir/"result.json";json proof={{"scope","isolated MVTO full-source overlay from frozenMV2PL/5ce, not root integration"},{"mode",mode}};try{
 fs::create_directories(dir);if(mode==std::string("normal")){need(!fs::exists(dir/"core"),"fresh directory");normal(dir/"core",proof);native_cursor(dir/"core",proof);metadata_budget(dir/"resource",proof);{StorageOptions o;o.recovery_mode="ARIES_PAGE";Engine e((dir/"aries-reject").u8string(),8,32u*1024u*1024u,o);auto s=e.open_session();error(e,s,"BEGIN PROTOCOL MVTO","ARIES_PROTOCOL");e.close_session(s);}{Engine e((dir/"core").u8string(),8);auto s=e.open_session();begin(e,s,true);value(e,s,13);value(e,s,21,2);sql(e,s,"VERIFY");sql(e,s,"COMMIT");e.close_session(s);}}
 else if(mode==std::string("hold-commit")||mode==std::string("hold-loser")){Engine e((dir/"core").u8string(),8);auto old=e.open_session(),w=e.open_session();begin(e,old,true);value(e,old,13);begin(e,w);sql(e,w,"UPDATE t SET v=77 WHERE id=1");if(mode==std::string("hold-commit"))sql(e,w,"COMMIT");value(e,old,13);proof["status"]="READY_FOR_EXTERNAL_TERMINATE";proof["pid"]=edudb_test::process_id();proof["events"]=events;write(receipt,proof);for(unsigned n=0;n<120;++n)std::this_thread::sleep_for(std::chrono::seconds(1));throw std::runtime_error("external kill not received");}
 else if(mode==std::string("recover-commit")||mode==std::string("recover-loser")){Engine e((dir/"core").u8string(),8);proof["startup"]=e.diagnostics();auto s=e.open_session();begin(e,s,true);value(e,s,mode==std::string("recover-commit")?77:13);value(e,s,21,2);sql(e,s,"VERIFY");sql(e,s,"COMMIT");e.close_session(s);}else throw std::runtime_error("unknown mode");
 proof["status"]="PASS";proof["checks"]=checks;proof["events"]=events;write(receipt,proof);std::cout<<"MVTO_TEST_PASS checks="<<checks<<"\n";return 0;
 }catch(const std::exception& ex){proof["status"]="FAIL";proof["checks"]=checks;proof["error"]=ex.what();proof["events"]=events;try{write(receipt,proof);}catch(...){}std::cerr<<ex.what()<<"\n";return 1;}}
